<script setup>
import { onMounted, ref } from 'vue'
import { useQuasar } from 'quasar'
import { api } from 'boot/axios'
const $q=useQuasar(), state=ref(null), token=ref(''), busy=ref(false)
const headers=()=>({headers:{Authorization:'Bearer '+localStorage.getItem('aito_admin_token')}})
async function load(){try{state.value=(await api.get('/admin/products/aitonotify/commerce-integration',headers())).data.data}catch(error){$q.notify({type:'negative',message:error.response?.data?.message||'Não foi possível conferir a integração comercial.'})}}
async function save(){busy.value=true;try{state.value=(await api.put('/admin/products/aitonotify/commerce-integration',{token:token.value},headers())).data.data;token.value='';$q.notify({type:'positive',message:'Chave comercial protegida e salva. Use o mesmo valor no NotifyFlow.'})}catch(error){$q.notify({type:'negative',message:error.response?.data?.message||'Não foi possível salvar a integração.'})}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="commerce-integration"><header><q-icon name="mdi-link-variant" size="28px"/><div><h3>Compras pelo WhatsApp do NotifyFlow</h3><p>A integração confirma o pagamento e libera a licença e o link privado de acesso ao comprador.</p></div><q-badge :color="state?.configured?'teal':'orange-9'" :label="state?.configured?'Configurada':'Configuração pendente'"/></header><p>Cadastre a mesma chave comercial usada pela integração de vendas do NotifyFlow. Ela é diferente do token de licença do produto e da chave OpenAI. O valor fica criptografado no servidor e não é exibido de volta.</p><q-banner v-if="state?.environmentLocked" rounded class="commerce-env">Esta instalação usa uma chave definida no ambiente de hospedagem. A substituição deve ser feita nesse ambiente.</q-banner><q-form v-else @submit.prevent="save"><q-input v-model="token" dark outlined type="password" autocomplete="new-password" label="Nova chave comercial compartilhada" minlength="32" maxlength="256" :disable="busy"/><q-btn unelevated color="teal-7" no-caps label="Salvar chave comercial" type="submit" :loading="busy" :disable="token.trim().length<32"/></q-form></section></template>
<style scoped>.commerce-integration{margin:24px 16px;padding:24px;border:1px solid #315e56;border-radius:16px;background:#061d20;color:#effffb}.commerce-integration header{display:flex;align-items:center;gap:12px}.commerce-integration header>div{flex:1;min-width:0}.commerce-integration h3{font-size:20px;line-height:1.3;margin:0}.commerce-integration p{font-size:12px;line-height:1.8;color:#acc9bd}.commerce-integration form{display:flex;gap:15px;align-items:start}.commerce-integration form>.q-field{flex:1}.commerce-env{background:#1f4137;color:#caeddd;font-size:12px}.commerce-integration :deep(.q-field__native),.commerce-integration :deep(.q-field__label){color:#d8eee3}.commerce-integration :deep(.q-field__control:before){border-color:#52766e}@media(max-width:700px){.commerce-integration{margin:16px 8px;padding:16px}.commerce-integration header{flex-wrap:wrap}.commerce-integration header>div{flex-basis:75%}.commerce-integration form{flex-direction:column;align-items:stretch}.commerce-integration h3{font-size:18px}}</style>
